import type { CompatData, CompatRule } from "./docs-data.ts";

const BANNER =
  "<!-- AUTOGENERATED by scripts/generate_compat_docs.py from benchbox/sql_compat/rules/. Do not edit by hand. Run `uv run scripts/generate_compat_docs.py` to refresh. -->";

function closing(lines: string[]): string {
  return `${lines.join("\n").replace(/\s+$/u, "")}\n`;
}

function rankOf(phaseOrder: string[], phase: string): number {
  const rank = phaseOrder.indexOf(phase);
  return rank < 0 ? phaseOrder.length : rank;
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function sortedRules(compat: CompatData): CompatRule[] {
  return [...compat.rules].sort(
    (left, right) =>
      compareText(left.platform, right.platform) ||
      rankOf(compat.phase_order, left.phase) - rankOf(compat.phase_order, right.phase) ||
      compareText(left.scope, right.scope) ||
      compareText(left.rule_id, right.rule_id),
  );
}

function platformsOf(rows: CompatRule[]): string[] {
  return [...new Set(rows.map((row) => row.platform))].sort(compareText);
}

function capabilityMatrix(compat: CompatData, rows: CompatRule[]): string {
  const platforms = platformsOf(rows);
  const counts = new Map<string, Map<string, number>>();
  for (const row of rows) {
    const phases = counts.get(row.platform) ?? new Map<string, number>();
    phases.set(row.phase, (phases.get(row.phase) ?? 0) + 1);
    counts.set(row.platform, phases);
  }
  const lines = [
    BANNER,
    "",
    "# SQL Compatibility Capability Matrix",
    "",
    "Every rule registered in `benchbox.sql_compat` is listed below. The registry is the authoritative source of compatibility policy; this document is regenerated from it. See [adr-sql-compat-phase-aware-pipeline.md](../development/adr/adr-sql-compat-phase-aware-pipeline.md) for the design.",
    "",
    `**Total registered rules:** ${rows.length}`,
    "",
    `**Platforms covered:** ${platforms.length}`,
    "",
    "## Phase coverage by platform",
    "",
  ];
  const phases = [...new Set(rows.map((row) => row.phase))].sort(
    (left, right) => rankOf(compat.phase_order, left) - rankOf(compat.phase_order, right),
  );
  lines.push(`| ${["platform", ...phases, "total"].join(" | ")} |`);
  lines.push(`|${["platform", ...phases, "total"].map(() => "---").join("|")}|`);
  for (const platform of platforms) {
    const cells = [platform];
    let total = 0;
    for (const phase of phases) {
      const count = counts.get(platform)?.get(phase) ?? 0;
      total += count;
      cells.push(count === 0 ? "-" : String(count));
    }
    cells.push(String(total));
    lines.push(`| ${cells.join(" | ")} |`);
  }
  lines.push("", "## Rules by platform", "");
  for (const platform of platforms) {
    lines.push(`### ${platform}`, "", "| phase | scope | action | support | failure mode | rule_id |", "|---|---|---|---|---|---|");
    for (const row of rows.filter((entry) => entry.platform === platform)) {
      lines.push(`| ${row.phase} | ${row.scope} | ${row.action} | ${row.support_level} | ${row.failure_mode} | \`${row.rule_id}\` |`);
    }
    lines.push("");
  }
  return closing(lines);
}

function skipBlocks(rows: CompatRule[], empty: string): string[] {
  if (rows.length === 0) return [empty, ""];
  const lines: string[] = [];
  for (const platform of platformsOf(rows)) {
    lines.push(`### ${platform}`, "", "| support | scope | phase | reason | rule_id |", "|---|---|---|---|---|");
    for (const row of rows.filter((entry) => entry.platform === platform)) {
      const reason = row.reason.replace(/\|/g, "\\|").replace(/\n/g, " ").trim();
      lines.push(`| ${row.support_level} | ${row.scope} | ${row.phase} | ${reason} | \`${row.rule_id}\` |`);
    }
    lines.push("");
  }
  return lines;
}

function skipReference(compat: CompatData, rows: CompatRule[]): string {
  const skipRows = rows.filter(
    (row) => compat.will_not_run_levels.includes(row.support_level) || compat.runs_with_caveats_levels.includes(row.support_level),
  );
  const willNotRun = skipRows.filter((row) => compat.will_not_run_levels.includes(row.support_level));
  const caveats = skipRows.filter((row) => compat.runs_with_caveats_levels.includes(row.support_level));
  const lines = [
    BANNER,
    "",
    "# SQL Compatibility Skip Reference",
    "",
    "Rules the registry applies to queries, benchmarks, and DDL statements. Split into two sections based on whether the outcome is user-visible in result counts. Each entry names the platform, the scope the rule applies to, the registered reason, and the rule_id you can grep for in `benchbox/sql_compat/rules/`.",
    "",
    `**Total rules:** ${skipRows.length}`,
    "",
    `**Platforms with rules:** ${platformsOf(skipRows).length}`,
    "",
  ];
  if (skipRows.length === 0) {
    lines.push("_No BLOCKED, SKIPPED_QUERY, SKIPPED_DDL_FRAGMENT, or INFORMATIONAL rules are registered._", "");
    return closing(lines);
  }
  lines.push(
    "## Will not run",
    "",
    "Queries or benchmarks that are **omitted from the result set** - either because the benchmark is refused at preflight (BLOCKED) or a specific query is excluded from execution (SKIPPED_QUERY). Users see these as missing entries in result counts.",
    "",
    ...skipBlocks(willNotRun, "_No BLOCKED or SKIPPED_QUERY rules are registered._"),
    "## Runs with caveats",
    "",
    "Benchmarks that **run end-to-end** but with documented internal gaps - either an auxiliary DDL statement is suppressed (SKIPPED_DDL_FRAGMENT) or a platform-level semantic guarantee is not enforced (INFORMATIONAL). Result counts are not affected; the caveat is noted for audit purposes.",
    "",
    ...skipBlocks(caveats, "_No SKIPPED_DDL_FRAGMENT or INFORMATIONAL rules are registered._"),
  );
  return closing(lines);
}

export function renderCompatPages(data: { compat: CompatData }): Map<string, string> {
  const rows = sortedRules(data.compat);
  return new Map([
    ["compat/capability-matrix.md", capabilityMatrix(data.compat, rows)],
    ["compat/skip-reference.md", skipReference(data.compat, rows)],
  ]);
}
